// 1. Virtual to Physical Address Translation (Simplified)

#define P_SHIFT 12         // Log2(Page Size)
#define P_MASK ((1 << P_SHIFT) - 1)

typedef uint64_t PTE;      // Page Table Entry type

uint64_t translate_address(uint64_t VA, uint64_t PTBR) {
    uint64_t VPN = VA >> P_SHIFT;
    uint64_t Offset = VA & P_MASK;

    // Simulate multi-level lookup or direct access
    PTE entry = fetch_pte(PTBR, VPN);

    if (!entry.ValidBit) return HARDWARE_FAULT;

    uint64_t PFN = entry.PageFrameNumber;
    uint64_t PA = (PFN << P_SHIFT) | Offset;
    return PA;
}

// 2. Structure of a Page Table Entry (PTE)

typedef struct {
    uint64_t PFN : 40;        // Physical Frame Number
    uint8_t Valid : 1;        // Is entry mapped?
    uint8_t R_W : 1;          // Read/Write permissions
    uint8_t User : 1;         // User vs Kernel page
    uint8_t Accessed : 1;     // Used recently
    uint8_t Dirty : 1;        // Has page been written to
    uint8_t Global : 1;       // Should not be flushed on context switch
    uint64_t Reserved : 18;
} PageTableEntry;

// 3. Handling a TLB Miss / Page Fault (OS Logic)

void handle_page_fault(uint64_t fault_addr, PageTable* current_pt) {
    uint64_t vpn = fault_addr >> P_SHIFT;

    if (PageTableWalk(current_pt, vpn) == NULL_ENTRY) {
        // Page does not exist in PT
        if (MemoryRegionCheck(vpn)) { // Valid VMA access?
            uint64_t pfn = OS_AllocateFrame();
            MapPTE(current_pt, vpn, pfn, WRITE_PERM);
            TLB_Invalidate(fault_addr);
            RestartInstruction();
        } else {
            SignalSegmentationFault();
        }
    }
}
